(function(root,factory){const value=factory();if(typeof module==='object')module.exports=value;else root.OmniSpeedCore=value})(globalThis,()=>{'use strict';const MIN=.25,MAX=4;function rate(value){if(typeof value!=='number'||!Number.isFinite(value))throw Error('INVALID_RATE');return Math.round(Math.max(MIN,Math.min(MAX,value))*100)/100}function step(value,direction,amount=.25){if(![-1,1].includes(direction)||![.1,.25,.5].includes(amount))throw Error('INVALID_STEP');return rate(value+direction*amount)}class Session{constructor(){this.records=new Map()}set(video,value){const next=rate(value);if(!this.records.has(video)&&this.records.size>=100){for(const[v,r]of this.records)if(v.isConnected===false){if(v.playbackRate===r.last)try{v.playbackRate=r.original}catch{}this.records.delete(v)}if(this.records.size>=100)throw Error('TRACK_LIMIT')}if(!this.records.has(video))this.records.set(video,{original:video.playbackRate,last:video.playbackRate});video.playbackRate=next;this.records.get(video).last=next;return next}restore(){for(const[v,r]of this.records)if(v.playbackRate===r.last)try{v.playbackRate=r.original}catch{}this.records.clear()}}return{MIN,MAX,rate,step,Session}});
